// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: deep-blue; icon-glyph: baseball-ball;
// Baseline Tennis for iPhone. Runs inside the free Scriptable app.
//  - Tap it in Scriptable (or its Home Screen icon) to open the full app.
//  - Add a Scriptable widget to your Home Screen and pick "Baseline" as its script for live scores
//    and alerts that update by themselves while the app is closed.
// Nothing here needs editing, except UPDATE_URL below if you set up automatic app updates (see README).
const BUILD = "2026-11-18 03:38";
const UPDATE_URL = "https://raw.githubusercontent.com/jdonnelly84/baseline/main/Baseline.js"; // where a newer Baseline.js is published; empty = never check

const START = "https://www.atptour.com/en/-/tournaments/calendar/tour"; // a small atptour.com page to open first
const LIVE = "https://app.atptour.com/api/v2/gateway/livematches/website?scoringTournamentLevel=tour";
const DEFAULT_FAVS = ["S0AG", "A0E2"]; // Sinner, Alcaraz, until the app has been opened once

const fm = FileManager.local();
const DIR = fm.joinPath(fm.documentsDirectory(), "baseline");
if (!fm.fileExists(DIR)) fm.createDirectory(DIR, true);
const STATE = fm.joinPath(DIR, "widget.json");
const readState = () => { try { return JSON.parse(fm.readString(STATE)) || {}; } catch (e) { return {}; } };
const writeState = (s) => { try { fm.writeString(STATE, JSON.stringify(s)); } catch (e) { /* ignore */ } };
const sleep = (ms) => new Promise((r) => Timer.schedule(ms, false, r));


// ---------------------------------------------------------------------------------------------- the app
async function runApp() {
  checkForUpdate(); // in the background; a newer version is used from the next launch
  const html = Data.fromBase64String(PACKED.replace(/\s+/g, "")).toRawString();
  const view = new WebView();
  // Open a real (small) atptour.com page first, so the app runs on atptour.com itself and reads the site the way
  // Safari does. If the site wants to check the browser first, that page is shown until the check is done.
  let state = "other";
  try { await view.loadURL(START); state = await pageState(view); } catch (e) { state = "other"; }
  let shown = null;
  if (state === "check") {
    shown = view.present(true);
    for (let i = 0; i < 90 && state === "check"; i++) { await sleep(1000); state = await pageState(view); }
  }
  let ok = false;
  if (state === "ready") ok = await inject(view, html);
  if (!ok) { // fallback: load the app with atptour.com as its address (no page visit first)
    await view.loadHTML(html, "https://www.atptour.com/en/");
  }
  const sync = Timer.schedule(30000, true, () => { saveSummary(view); });
  await (shown || view.present(true));
  sync.invalidate();
  await saveSummary(view);
}

async function pageState(view) {
  try {
    const s = await view.evaluateJavaScript(`(function(){var t=(document.body&&document.body.innerText||"").slice(0,200);return JSON.stringify({host:location.host,title:document.title||"",json:/^\\s*[\\[{]/.test(t)})})()`);
    const p = JSON.parse(s);
    if (p.host === "www.atptour.com" && p.json) return "ready";
    if (/just a moment|attention required|checking/i.test(p.title)) return "check";
    return "other";
  } catch (e) { return "other"; }
}

async function inject(view, html) {
  try {
    await view.evaluateJavaScript(`document.open();document.write(${JSON.stringify(html)});document.close();true`);
    await sleep(400);
    return await view.evaluateJavaScript(`!!window.BaselineApp`);
  } catch (e) { return false; }
}

async function saveSummary(view) {
  try {
    const s = await view.evaluateJavaScript(`JSON.stringify(window.BaselineApp && window.BaselineApp.widget ? window.BaselineApp.widget() : null)`);
    const sum = JSON.parse(s);
    if (sum && sum.favs) { const st = readState(); st.summary = sum; writeState(st); }
  } catch (e) { /* the app may still be loading */ }
}

async function checkForUpdate() {
  if (!/^https:\/\//.test(UPDATE_URL)) return;
  try {
    const st = readState();
    if (st.updateCheckedAt && Date.now() - st.updateCheckedAt < 6 * 3600e3) return;
    st.updateCheckedAt = Date.now(); writeState(st);
    const req = new Request(UPDATE_URL + (UPDATE_URL.includes("?") ? "&" : "?") + "t=" + Date.now());
    req.timeoutInterval = 30;
    const text = await req.loadString();
    const m = text.match(/const BUILD = "([^"]+)"/);
    if (!m || m[1] <= BUILD || !text.includes("Data.fromBase64String")) return;
    FileManager.local().writeString(module.filename, text);
  } catch (e) { /* try again later */ }
}

// ---------------------------------------------------------------------------------------------- the widget
async function runWidget() {
  const st = readState();
  const favs = (st.summary && st.summary.favs && st.summary.favs.length ? st.summary.favs : DEFAULT_FAVS).map((x) => String(x).toUpperCase());
  const feed = await loadLive();
  const matches = feed ? flatten(feed) : (st.lastMatches || []);
  if (feed) { st.lastMatches = matches; st.liveAt = Date.now(); }
  if (feed) notifyChanges(st, matches, favs);
  writeState(st);
  const w = buildWidget(matches, favs, st, !!feed);
  const anyLive = matches.some((m) => m.status === "P" || m.status === "W" || m.status === "C");
  w.refreshAfterDate = new Date(Date.now() + (anyLive ? 5 : 20) * 60e3); // iOS decides the exact timing
  w.url = URLScheme.forRunningScript();
  if (config.runsInWidget) Script.setWidget(w);
  else await w.presentMedium();
}

async function loadLive() {
  try { // plain request first: small and quick
    const r = new Request(LIVE); r.timeoutInterval = 15; r.headers = { Accept: "application/json" };
    const j = await r.loadJSON();
    if (j && j.Data) return j;
  } catch (e) { /* blocked or offline */ }
  try { // otherwise read it the way Safari would
    const v = new WebView();
    await v.loadURL(LIVE);
    const t = await v.evaluateJavaScript(`document.body ? document.body.innerText : ""`);
    const j = JSON.parse(t);
    if (j && j.Data) return j;
  } catch (e) { /* show the last saved scores */ }
  return null;
}

function flatten(feed) {
  const out = [];
  for (const t of (feed.Data && feed.Data.LiveMatchesTournamentsOrdered) || []) {
    for (const m of t.LiveMatches || []) {
      const team = (T) => {
        const ps = [T && T.Player, T && T.Partner].filter((p) => p && p.PlayerId);
        return {
          ids: ps.map((p) => p.PlayerId.toUpperCase()),
          name: ps.map((p) => (ps.length > 1 ? "" : (p.PlayerFirstName || "").slice(0, 1) + ". ") + (p.PlayerLastName || "")).join("/"),
          sets: ((T && T.SetScores) || []).filter((s) => s.SetScore !== null && s.SetScore !== undefined).map((s) => s.SetScore),
          game: (T && T.GameScore) || "", seed: (T && T.Seed) || null,
        };
      };
      out.push({ key: t.EventId + "-" + m.MatchId, city: t.EventCity || t.EventTitle, round: m.RoundName || "", doubles: !!m.IsDoubles,
        status: m.MatchStatus, server: m.ServerTeam, winner: m.WinningPlayerId ? m.WinningPlayerId.toUpperCase() : null,
        court: m.CourtName || "", a: team(m.PlayerTeam), b: team(m.OpponentTeam) });
    }
  }
  return out;
}

const isLive = (m) => m.status === "P";
const isOn = (m) => ["P", "W", "C", "S", "D"].includes(m.status);
const isDone = (m) => ["F", "R", "X"].includes(m.status);
const hasFav = (m, favs) => m.a.ids.concat(m.b.ids).some((id) => favs.includes(id));
const roundShort = (r) => (r || "").replace("Round of ", "R").replace(/Quarter-?finals/i, "QF").replace(/Semi-?finals/i, "SF").replace(/^Final$/i, "F").replace(/Round Robin/i, "RR");
const score = (m) => m.a.sets.map((g, i) => `${g}-${m.b.sets[i] == null ? "" : m.b.sets[i]}`).join(" ");
const winnerSide = (m) => (m.winner ? (m.a.ids.includes(m.winner) ? "a" : m.b.ids.includes(m.winner) ? "b" : null) : null);
const STATUS = { P: "LIVE", W: "WARM-UP", C: "ON COURT", S: "SUSPENDED", D: "DELAYED", F: "FINAL", R: "RETIRED", X: "FINAL" };

function notifyChanges(st, matches, favs) {
  const prev = st.seen || null;
  const seen = {};
  for (const m of matches) seen[m.key] = m.status;
  st.seen = seen;
  if (!prev) return; // first run: nothing to compare with
  for (const m of matches) {
    if (m.doubles || !hasFav(m, favs)) continue;
    const before = prev[m.key];
    const mine = m.a.ids.some((id) => favs.includes(id)) ? m.a : m.b;
    const opp = mine === m.a ? m.b : m.a;
    let title = null, body = null;
    if (isLive(m) && before !== "P" && !isDone({ status: before || "" }) && before !== "S") { title = `${mine.name} is on court`; body = `vs ${opp.name} · ${m.city} ${roundShort(m.round)}`; }
    else if (isDone(m) && before && !isDone({ status: before })) {
      const w = winnerSide(m); const won = w ? (w === "a") === (mine === m.a) : null;
      title = won === null ? `${mine.name} vs ${opp.name}: final` : won ? `${mine.name} beat ${opp.name}` : `${mine.name} lost to ${opp.name}`;
      body = `${score(m)} · ${m.city} ${roundShort(m.round)}`;
    }
    if (title) { try { const n = new Notification(); n.title = title; n.body = body; n.openURL = URLScheme.forRunningScript(); n.schedule(); } catch (e) { /* notifications off */ } }
  }
}

// Widget layout ----------------------------------------------------------------------------------------
const C = { bg1: new Color("#1a1f6e"), bg2: new Color("#3b23a8"), fg: Color.white(), muted: new Color("#b9c0e6"), live: new Color("#ff4d6d"), win: new Color("#3ddc97"), star: new Color("#ffd166") };

function buildWidget(matches, favs, st, fresh) {
  const fam = config.widgetFamily || "medium";
  const w = new ListWidget();
  const g = new LinearGradient(); g.colors = [C.bg1, C.bg2]; g.locations = [0, 1]; w.backgroundGradient = g;
  w.setPadding(12, 14, 10, 14);
  const big = fam === "large" || fam === "extraLarge";
  const max = fam === "small" ? 1 : big ? 5 : 2;

  const head = w.addStack(); head.centerAlignContent();
  const t = head.addText("BASELINE"); t.font = Font.heavySystemFont(11); t.textColor = C.fg; t.textOpacity = 0.9;
  head.addSpacer();
  const liveCount = matches.filter((m) => isLive(m) && !m.doubles).length;
  if (liveCount) { const l = head.addText(`● ${liveCount} LIVE`); l.font = Font.boldSystemFont(10); l.textColor = C.live; }
  w.addSpacer(6);

  // Followed players first, then other singles that are on, then today's finished matches.
  const rank = (m) => (hasFav(m, favs) ? 0 : 10) + (isLive(m) ? 0 : isOn(m) ? 1 : 2) + (m.doubles ? 5 : 0);
  const pick = matches.filter((m) => !m.doubles || hasFav(m, favs)).sort((a, b) => rank(a) - rank(b)).slice(0, max);
  for (const m of pick) { addMatch(w, m, favs, fam === "small"); w.addSpacer(fam === "small" ? 4 : 7); }

  const players = (st.summary && st.summary.players) || [];
  const showPlayers = big || !pick.length;
  if (showPlayers && players.length) {
    if (pick.length) w.addSpacer(2);
    for (const p of players.slice(0, big ? 4 : fam === "small" ? 1 : 2)) {
      const row = w.addStack(); row.layoutVertically();
      const n = row.addText(`★ ${p.name}`); n.font = Font.boldSystemFont(12); n.textColor = C.fg; n.lineLimit = 1;
      const s = row.addText(p.status || ""); s.font = Font.systemFont(11); s.textColor = p.live ? C.live : C.muted; s.lineLimit = 2;
      w.addSpacer(5);
    }
  } else if (!pick.length) {
    const e = w.addText("No ATP matches on right now. Open Baseline once so the widget knows your players.");
    e.font = Font.systemFont(12); e.textColor = C.muted;
  }
  w.addSpacer();
  const foot = w.addText(fresh ? `Updated ${new Date().toLocaleTimeString("en-NZ", { hour: "numeric", minute: "2-digit" })}` : `Offline · last update ${st.liveAt ? new Date(st.liveAt).toLocaleTimeString("en-NZ", { hour: "numeric", minute: "2-digit" }) : "never"}`);
  foot.font = Font.systemFont(9); foot.textColor = C.muted; foot.textOpacity = 0.8;
  return w;
}

function addMatch(w, m, favs, small) {
  const meta = w.addStack(); meta.centerAlignContent();
  const where = meta.addText(`${m.city} · ${roundShort(m.round)}`.toUpperCase()); where.font = Font.semiboldSystemFont(9); where.textColor = C.muted; where.lineLimit = 1;
  meta.addSpacer();
  const s = meta.addText(STATUS[m.status] || m.status || ""); s.font = Font.boldSystemFont(9); s.textColor = isLive(m) ? C.live : C.muted;
  w.addSpacer(2);
  const ws = winnerSide(m);
  for (const side of ["a", "b"]) {
    const tm = m[side]; const other = m[side === "a" ? "b" : "a"];
    const row = w.addStack(); row.centerAlignContent();
    const fav = tm.ids.some((id) => favs.includes(id));
    const serving = isLive(m) && ((side === "a" && m.server === 0) || (side === "b" && m.server === 1));
    const name = row.addText(`${fav ? "★ " : ""}${tm.name}${serving ? " •" : ""}`);
    name.font = ws === side || (!ws && fav) ? Font.boldSystemFont(small ? 12 : 13) : Font.mediumSystemFont(small ? 12 : 13);
    name.textColor = fav ? C.star : C.fg; name.lineLimit = 1; name.minimumScaleFactor = 0.7;
    if (ws && ws !== side) name.textOpacity = 0.65;
    row.addSpacer();
    tm.sets.forEach((g, i) => {
      const cell = row.addStack(); cell.size = new Size(small ? 12 : 15, 16);
      const tx = cell.addText(String(g)); tx.font = Font.boldMonospacedSystemFont(small ? 12 : 13);
      const lost = other.sets[i] != null && g < other.sets[i];
      tx.textColor = lost ? C.muted : C.fg;
    });
    if (isLive(m) && tm.game !== "" && tm.game != null) {
      const cell = row.addStack(); cell.size = new Size(small ? 20 : 24, 16);
      const tx = cell.addText(String(tm.game)); tx.font = Font.boldMonospacedSystemFont(small ? 11 : 12); tx.textColor = C.win;
    }
  }
}

// ---------------------------------------------------------------------------------------------- packed app
// The whole Baseline app (built 2026-11-18 03:38), packed as one block of text.
const PACKED = `


































`;

// ---------------------------------------------------------------------------------------------- start
if (config.runsInWidget || (args.queryParameters && args.queryParameters.widget)) await runWidget();
else await runApp();
Script.complete();
